public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        int q = Integer.parseInt(first);
        TreeMap<Integer, Integer> map = new TreeMap<>();
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            String cmd = fs.next();
            if (cmd == null) break;

            if (cmd.equals("insert")) {
                int x = fs.nextInt();
                int c = map.getOrDefault(x, 0) + 1;
                map.put(x, c);
                out.append(c).append('\n');
            } else if (cmd.equals("find")) {
                int x = fs.nextInt();
                out.append(map.getOrDefault(x, 0)).append('\n');
            } else if (cmd.equals("delete")) {
                int x = fs.nextInt();
                int c = map.getOrDefault(x, 0);
                out.append(c).append('\n');
                if (c > 0) map.remove(x);
            } else if (cmd.equals("dump")) {
                int l = fs.nextInt();
                int r = fs.nextInt();
                NavigableMap<Integer, Integer> sub = map.subMap(l, true, r, true);
                boolean firstPrinted = true;
                for (Map.Entry<Integer, Integer> e : sub.entrySet()) {
                    int val = e.getKey();
                    int cnt = e.getValue();
                    for (int k = 0; k < cnt; k++) {
                        if (!firstPrinted) out.append(' ');
                        out.append(val);
                        firstPrinted = false;
                    }
                }
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

