#define MAX_NODES 200005

typedef struct Node {
    int key;
    int cnt;
    int height;
    struct Node *left;
    struct Node *right;
} Node;

Node nodes[MAX_NODES];
int node_count = 0;

Node* new_node(int key) {
    Node* node = &nodes[node_count++];
    node->key = key;
    node->cnt = 1;
    node->height = 1;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int max(int a, int b) {
    return (a > b) ? a : b;
}

int height(Node* n) {
    return n ? n->height : 0;
}

int get_balance(Node* n) {
    return n ? height(n->left) - height(n->right) : 0;
}

Node* right_rotate(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;
    return x;
}

Node* left_rotate(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;
    return y;
}

Node* insert(Node* node, int key) {
    if (!node) return new_node(key);
    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);
    else {
        node->cnt++;
        return node;
    }
    node->height = 1 + max(height(node->left), height(node->right));
    int balance = get_balance(node);
    if (balance > 1 && key < node->left->key)
        return right_rotate(node);
    if (balance < -1 && key > node->right->key)
        return left_rotate(node);
    if (balance > 1 && key > node->left->key) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }
    if (balance < -1 && key < node->right->key) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }
    return node;
}

Node* min_value_node(Node* node) {
    Node* current = node;
    while (current->left)
        current = current->left;
    return current;
}

Node* delete_node(Node* root, int key) {
    if (!root) return NULL;
    if (key < root->key)
        root->left = delete_node(root->left, key);
    else if (key > root->key)
        root->right = delete_node(root->right, key);
    else {
        if (root->cnt > 1) {
            root->cnt--;
            return root;
        }
        if (!root->left || !root->right) {
            Node* temp = root->left ? root->left : root->right;
            return temp;
        } else {
            Node* temp = min_value_node(root->right);
            root->key = temp->key;
            root->cnt = temp->cnt;
            temp->cnt = 1;
            root->right = delete_node(root->right, temp->key);
        }
    }
    if (!root) return root;
    root->height = 1 + max(height(root->left), height(root->right));
    int balance = get_balance(root);
    if (balance > 1 && get_balance(root->left) >= 0)
        return right_rotate(root);
    if (balance > 1 && get_balance(root->left) < 0) {
        root->left = left_rotate(root->left);
        return right_rotate(root);
    }
    if (balance < -1 && get_balance(root->right) <= 0)
        return left_rotate(root);
    if (balance < -1 && get_balance(root->right) > 0) {
        root->right = right_rotate(root->right);
        return left_rotate(root);
    }
    return root;
}

int count_key(Node* root, int key) {
    if (!root) return 0;
    if (key < root->key)
        return count_key(root->left, key);
    else if (key > root->key)
        return count_key(root->right, key);
    else
        return root->cnt;
}

void delete_all(Node** root, int key) {
    while (count_key(*root, key) > 0) {
        *root = delete_node(*root, key);
    }
}

