typedef struct Node {
    int key, priority, cnt, size;
    struct Node *left, *right;
} Node;

Node* newNode(int key) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->key = key;
    n->priority = rand();
    n->cnt = 1;
    n->size = 1;
    n->left = n->right = NULL;
    return n;
}

void update(Node* n) {
    if (n) n->size = n->cnt + (n->left ? n->left->size : 0) + (n->right ? n->right->size : 0);
}

Node* rotL(Node* n) { Node* r = n->right; n->right = r->left; r->left = n; update(n); update(r); return r; }
Node* rotR(Node* n) { Node* l = n->left; n->left = l->right; l->right = n; update(n); update(l); return l; }

Node* insert(Node* n, int key) {
    if (!n) return newNode(key);
    if (key == n->key) { n->cnt++; n->size++; return n; }
    if (key < n->key) { n->left = insert(n->left, key); if (n->left->priority > n->priority) n = rotR(n); }
    else { n->right = insert(n->right, key); if (n->right->priority > n->priority) n = rotL(n); }
    update(n); return n;
}

int countKey(Node* n, int key) {
    if (!n) return 0;
    if (key == n->key) return n->cnt;
    if (key < n->key) return countKey(n->left, key);
    return countKey(n->right, key);
}

Node* deleteKey(Node* n, int key) {
    if (!n) return NULL;
    if (key < n->key) { n->left = deleteKey(n->left, key); update(n); return n; }
    if (key > n->key) { n->right = deleteKey(n->right, key); update(n); return n; }
    if (!n->left && !n->right) { free(n); return NULL; }
    if (!n->left || (n->right && n->right->priority > n->left->priority)) { n = rotL(n); n->left = deleteKey(n->left, key); }
    else { n = rotR(n); n->right = deleteKey(n->right, key); }
    update(n); return n;
}

void dumpRange(Node* n, int a, int b) {
    if (!n) return;
    if (n->key > a) dumpRange(n->left, a, b);
    if (n->key >= a && n->key <= b) { for (int i = 0; i < n->cnt; i++) printf("%d\n", n->key); }
    if (n->key < b) dumpRange(n->right, a, b);
}

