typedef struct Node {
    int key;
    int cnt;
    int pri;
    struct Node *l, *r;
} Node;

static Node* new_node(int key) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->key = key;
    n->cnt = 1;
    n->pri = rand();
    n->l = n->r = NULL;
    return n;
}

static void rotate_left(Node **t) {
    Node *r = (*t)->r;
    (*t)->r = r->l;
    r->l = *t;
    *t = r;
}

static void rotate_right(Node **t) {
    Node *l = (*t)->l;
    (*t)->l = l->r;
    l->r = *t;
    *t = l;
}

static void insert(Node **t, int key) {
    if (*t == NULL) {
        *t = new_node(key);
        return;
    }
    if (key == (*t)->key) {
        (*t)->cnt++;
    } else if (key < (*t)->key) {
        insert(&(*t)->l, key);
        if ((*t)->l && (*t)->l->pri > (*t)->pri) rotate_right(t);
    } else {
        insert(&(*t)->r, key);
        if ((*t)->r && (*t)->r->pri > (*t)->pri) rotate_left(t);
    }
}

static int find_count(Node *t, int key) {
    while (t) {
        if (key == t->key) return t->cnt;
        t = (key < t->key) ? t->l : t->r;
    }
    return 0;
}

static void delete_all(Node **t, int key) {
    if (*t == NULL) return;
    if (key < (*t)->key) {
        delete_all(&(*t)->l, key);
    } else if (key > (*t)->key) {
        delete_all(&(*t)->r, key);
    } else {
        Node *cur = *t;
        if (!cur->l) {
            *t = cur->r;
            free(cur);
        } else if (!cur->r) {
            *t = cur->l;
            free(cur);
        } else {
            if (cur->l->pri > cur->r->pri) {
                rotate_right(t);
                delete_all(&(*t)->r, key);
            } else {
                rotate_left(t);
                delete_all(&(*t)->l, key);
            }
        }
    }
}

static void dump_range(Node *t, int a, int b, int *first) {
    if (!t) return;
    if (t->key > a) dump_range(t->l, a, b, first);
    if (a <= t->key && t->key <= b) {
        for (int i = 0; i < t->cnt; i++) {
            if (!*first) printf(" ");
            printf("%d", t->key);
            *first = 0;
        }
    }
    if (t->key < b) dump_range(t->r, a, b, first);
}

static void free_tree(Node *t) {
    if (!t) return;
    free_tree(t->l);
    free_tree(t->r);
    free(t);
}

int main(void) {
