import sys
from random import randint

# Treap node storing:
# key   : integer value
# cnt   : multiplicity of key
# size  : total number of elements in subtree counting multiplicity
class Node:
    __slots__ = ("key", "prio", "cnt", "size", "left", "right")

    def __init__(self, key):
        self.key = key
        self.prio = randint(1, 1 << 30)
        self.cnt = 1
        self.size = 1
        self.left = None
        self.right = None


def sz(t):
    return t.size if t else 0


def upd(t):
    if t:
        t.size = t.cnt + sz(t.left) + sz(t.right)


def rotate_right(t):
    x = t.left
    t.left = x.right
    x.right = t
    upd(t)
    upd(x)
    return x


def rotate_left(t):
    x = t.right
    t.right = x.left
    x.left = t
    upd(t)
    upd(x)
    return x


def insert(t, key):
    if t is None:
        return Node(key)
    if key == t.key:
        t.cnt += 1
    elif key < t.key:
        t.left = insert(t.left, key)
        if t.left.prio < t.prio:
            t = rotate_right(t)
    else:
        t.right = insert(t.right, key)
        if t.right.prio < t.prio:
            t = rotate_left(t)
    upd(t)
    return t


def count_key(t, key):
    while t:
        if key == t.key:
            return t.cnt
        elif key < t.key:
            t = t.left
        else:
            t = t.right
    return 0


def merge(a, b):
    if not a or not b:
        return a or b
    if a.prio < b.prio:
        a.right = merge(a.right, b)
        upd(a)
        return a
    else:
        b.left = merge(a, b.left)
        upd(b)
        return b


def erase_all(t, key):
    if t is None:
        return None, 0
    if key == t.key:
        removed = t.cnt
        return merge(t.left, t.right), removed
    elif key < t.key:
        t.left, removed = erase_all(t.left, key)
        upd(t)
        return t, removed
    else:
        t.right, removed = erase_all(t.right, key)
        upd(t)
        return t, removed


def range_collect(t, l, r, out):
    if t is None:
        return
    if t.key > l:
        range_collect(t.left, l, r, out)
    if l <= t.key <= r:
        if t.cnt == 1:
            out.append(str(t.key))
        else:
            out.extend([str(t.key)] * t.cnt)
    if t.key < r:
        range_collect(t.right, l, r, out)


def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    # Expected command format:
    # insert x
    # find x
    # delete x
    # dump l r
    #
    # Output:
    # find   -> count of x
    # delete -> number of deleted instances
    # dump   -> elements in [l, r] in ascending order, space-separated; print EMPTY if none
    #
    # If the first line is an integer, treat it as number of operations.

    start = 0
    if data[0].strip().isdigit():
        q = int(data[0].strip())
        lines = data[1:1 + q]
    else:
        lines = data

    root = None
    ans = []

    for line in lines:
        if not line.strip():
            continue
        parts = line.split()
        cmd = parts[0].lower()

        if cmd in ("insert", "i"):
            x = int(parts[1])
            root = insert(root, x)

        elif cmd in ("find", "count", "c", "f"):
            x = int(parts[1])
            ans.append(str(count_key(root, x)))

        elif cmd in ("delete", "del", "d", "remove"):
            x = int(parts[1])
            root, removed = erase_all(root, x)
            ans.append(str(removed))

        elif cmd in ("dump", "range", "print", "p"):
            l = int(parts[1])
            r = int(parts[2])
            if l > r:
                l, r = r, l
            out = []
            range_collect(root, l, r, out)
            ans.append(" ".join(out) if out else "EMPTY")

    sys.stdout.write("\n".join(ans))


if __name__ == "__main__":
    main()
